import React from 'react';
import './ServicioDetalle.css';

const ConsultoriaEmpresarial = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Consultoría Empresarial</h2>
    <p>Apoyo estratégico para el crecimiento y desarrollo de tu empresa, análisis de procesos, gestión de riesgos y mejora continua.</p>
  </div>
);

export default ConsultoriaEmpresarial;
